import { pgTable, serial, text, jsonb, timestamp } from "drizzle-orm/pg-core";

// The narrative sections of a country brief, generated by the AI prose engine
// (see artifacts/api-server/src/lib/countryProse.ts). implications and watchNext
// are bullet lists; the rest are paragraphs.
export interface CountryProseSections {
  executiveSummary: string;
  situation: string;
  whatHappened: string;
  whatMatters: string;
  implications: string[];
  watchNext: string[];
  polestarView: string;
  // Forward-looking outlook paragraph. Only the PNG country brief (variant
  // "png") populates this; the generic country report leaves it undefined.
  outlook?: string;
}

// Cache of AI-generated country-report prose, keyed one-row-per-country.
//
// `fingerprint` is a hash of the exact window incidents the prose was grounded
// on (plus the prompt version). When the underlying data changes the
// fingerprint changes and the prose is regenerated, so the cache can never go
// stale — the historical reason the overview/trend_summary/implications columns
// on country_reports were retired. `edited` holds analyst overrides bound to the
// SAME fingerprint; it is dropped whenever the prose is regenerated, so an edit
// only ever describes the data snapshot it was written against.
export const countryReportProseTable = pgTable("country_report_prose", {
  id: serial("id").primaryKey(),
  slug: text("slug").notNull().unique(),
  fingerprint: text("fingerprint").notNull(),
  sections: jsonb("sections").$type<CountryProseSections>().notNull(),
  edited: jsonb("edited").$type<CountryProseSections | null>(),
  model: text("model").notNull(),
  generatedAt: timestamp("generated_at", { withTimezone: true }).notNull().defaultNow(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type CountryReportProse = typeof countryReportProseTable.$inferSelect;
export type InsertCountryReportProse = typeof countryReportProseTable.$inferInsert;
